package com.alpha.showcase.common.media

import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.size
import androidx.compose.runtime.mutableFloatStateOf
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Canvas
import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.drawscope.CanvasDrawScope
import androidx.compose.ui.graphics.painter.Painter
import androidx.compose.ui.graphics.toPixelMap
import androidx.compose.ui.platform.testTag
import androidx.compose.ui.test.ExperimentalTestApi
import androidx.compose.ui.test.captureToImage
import androidx.compose.ui.test.onNodeWithTag
import androidx.compose.ui.test.runComposeUiTest
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.Density
import androidx.compose.ui.unit.LayoutDirection
import com.alpha.facedetection.createFaceInspector
import com.alpha.facedetection.FaceInspectionResult
import io.github.alexzhirkevich.compottie.Compottie
import io.github.alexzhirkevich.compottie.LottieComposition
import io.github.alexzhirkevich.compottie.LottieLogger
import io.github.alexzhirkevich.compottie.rememberLottiePainter
import kotlinx.coroutines.test.runTest
import org.jetbrains.skia.Image as SkiaImage
import kotlin.io.encoding.Base64
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue
import kotlin.time.measureTime

/** Integration checks must link both the real OpenCV bridge and Compose/Skia. */
@OptIn(ExperimentalTestApi::class)
class IosMediaRenderingTest {
    @Test
    fun jpegDecodesAlongsideFaceDetection() = runTest {
        val jpeg = Base64.decode(JPEG)
        // Exercise both callers in the same process; isolated decoder tests miss ABI collisions.
        assertEquals(FaceInspectionResult.NO_FACE, createFaceInspector().inspect(jpeg))
        val image = SkiaImage.makeFromEncoded(jpeg)
        try {
            assertTrue(image.width > 0 && image.height > 0)
        } finally {
            image.close()
        }
    }

    @Test
    fun lottieGradientDrawsWithoutLinkageErrors() {
        val errors = mutableListOf<Throwable>()
        val previous = Compottie.logger
        Compottie.logger = object : LottieLogger {
            override fun info(message: String) = Unit
            override fun warn(message: String) = Unit
            override fun error(message: String, throwable: Throwable) { errors += throwable }
        }
        try {
            val composition = LottieComposition.parse(GRADIENT)
            val progress = mutableFloatStateOf(0.5f)
            lateinit var painter: Painter
            runComposeUiTest {
                setContent {
                    painter = rememberLottiePainter(composition, progress = { progress.floatValue })
                    Image(
                        painter = painter,
                        contentDescription = null,
                        modifier = Modifier.size(100.dp).testTag("gradient"),
                    )
                }
                waitForIdle()
                val pixels = onNodeWithTag("gradient").captureToImage().toPixelMap()
                runOnIdle {
                    val canvas = Canvas(ImageBitmap(100, 100))
                    val scope = CanvasDrawScope()
                    val duration = measureTime {
                        repeat(120) { frame ->
                            progress.floatValue = frame / 120f
                            scope.draw(Density(1f), LayoutDirection.Ltr, canvas, Size(100f, 100f)) {
                                with(painter) { draw(size) }
                            }
                        }
                    }
                    println("Lottie gradient: 120 frames in $duration; ${errors.size} render errors")
                }
                assertTrue(errors.isEmpty(), errors.firstOrNull().toString())
                // A swallowed drawing failure must not pass as a blank successful frame.
                assertTrue(pixels[pixels.width / 4, pixels.height / 2].red > 0.5f)
                assertTrue(pixels[pixels.width * 3 / 4, pixels.height / 2].blue > 0.5f)
            }
        } finally {
            Compottie.logger = previous
        }
    }

    private companion object {
        const val GRADIENT = """{"v":"5.7.0","fr":30,"ip":0,"op":30,"w":100,"h":100,"layers":[{"ty":4,"ind":1,"ip":0,"op":30,"st":0,"ks":{"o":{"a":0,"k":100},"r":{"a":0,"k":0},"p":{"a":0,"k":[0,0]},"a":{"a":0,"k":[0,0]},"s":{"a":0,"k":[100,100]}},"shapes":[{"ty":"rc","p":{"a":0,"k":[50,50]},"s":{"a":0,"k":[100,100]},"r":{"a":0,"k":0}},{"ty":"gf","o":{"a":0,"k":100},"r":1,"t":1,"s":{"a":0,"k":[0,50]},"e":{"a":0,"k":[100,50]},"g":{"p":2,"k":{"a":0,"k":[0,1,0,0,1,0,0,1]}}}]}]}"""
        const val JPEG = ""
    }
}
